import assert from'node:assert/strict';import{readFile,writeFile,mkdtemp,cp,mkdir}from'node:fs/promises';import{resolve,join,relative,isAbsolute,dirname}from'node:path';
export async function coldFieldMaterialActualInputQaV1(){
 const root=resolve(process.env.IDMS_COLD_FIELD_MATERIAL_QA_CASE??''),work=resolve(process.env.IDMS_COLD_FIELD_MATERIAL_QA_WORK??'');assert(process.env.IDMS_COLD_FIELD_MATERIAL_QA_CASE&&process.env.IDMS_COLD_FIELD_MATERIAL_QA_WORK);const r=JSON.parse(await readFile(join(root,'verification.json'),'utf8'));assert(r.passed&&r.checks.length===32&&r.fieldColdSourceCreation.sources.length===2);await mkdir(work,{recursive:true});
 const sources=r.fieldColdSourceCreation.sources,original=join(root,'field-site-materials'),container=await mkdtemp(join(work,'case-')),directory=join(container,'materials');await cp(original,directory,{recursive:true,errorOnExist:true,force:false});const configurationFile=join(directory,'activation-materials.json'),configuration=JSON.parse(await readFile(configurationFile,'utf8'));
 const rebase=path=>{const rel=relative(original,resolve(path));assert(rel&&!rel.startsWith('..')&&!isAbsolute(rel));return join(directory,rel);};configuration.intakeConfigurationFile=rebase(configuration.intakeConfigurationFile);for(const edge of configuration.edges)edge.configurationFile=rebase(edge.configurationFile);await writeFile(configurationFile,JSON.stringify(configuration));
 const json=async p=>JSON.parse(await readFile(p,'utf8')),save=(p,v)=>writeFile(p,JSON.stringify(v)),edgeFile=configuration.edges[0].configurationFile,edge=await json(edgeFile),profileFile=resolve(dirname(edgeFile),edge.profileFile),profile=await json(profileFile),intake=await json(configuration.intakeConfigurationFile);
 return{directory,configurationFile,configuration,edgeFile,edge,profileFile,profile,intake,json,save,sourceModes:sources,context:{trust:sources.find(v=>v.mode==='ENABLED').trust,tenantId:configuration.tenantId,roots:[directory]}};
}
